import{_ as s,o,c as i,a0 as t}from"./chunks/framework.CNXp-E7Q.js";const k=JSON.parse('{"title":"How-to: package bupha fleets with tamias","description":"","frontmatter":{},"headers":[],"relativePath":"how-to/tamias-bundles.md","filePath":"how-to/tamias-bundles.md"}'),a={name:"how-to/tamias-bundles.md"};function d(n,e,r,c,h,l){return o(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="how-to-package-bupha-fleets-with-tamias" tabindex="-1">How-to: package bupha fleets with tamias <a class="header-anchor" href="#how-to-package-bupha-fleets-with-tamias" aria-label="Permalink to &quot;How-to: package bupha fleets with tamias&quot;">​</a></h1><p>A bupha fleet — watcher unit + operator config + webhook wiring — ships as a tamias content bundle (<code>type: bupha</code>). tamias owns the package lifecycle (fetch, install store, provider units, hooks); bupha owns what runs inside. The shipped examples live in <code>libraries/</code>: <code>ci-gate</code> (push-to-verdict gate on <code>main</code>), <code>docs-deploy</code> (push to <code>docs</code> → site deploy → <code>docs/deploy</code> status), and <code>ci-ingress</code> — a <code>peregrin-bundle</code>, not <code>type: bupha</code>: the forge webhook → <code>ci-job</code> entity campaign that feeds the worker fleet (CI orchestration knowledge lives here even though the bundle type is peregrin&#39;s).</p><h2 id="the-type-bupha-contract" tabindex="-1">The <code>type: bupha</code> contract <a class="header-anchor" href="#the-type-bupha-contract" aria-label="Permalink to &quot;The \`type: bupha\` contract&quot;">​</a></h2><p>Two files make a bundle:</p><ul><li><strong><code>tamias.yaml</code></strong> — the package manifest. <code>provider:</code> declares the systemd unit(s) (<code>&lt;provider.name&gt;-&lt;service&gt;</code>), the env file, and <code>ingress[]</code> — the public URL, listen address, and the GitHub hooks to manage. <code>verbs:</code> is advisory for <code>tamias provider list</code>/<code>tamias run</code>.</li><li><strong><code>fleet.toml</code></strong> — a <em>complete</em> <code>bupha_core::Config</code> doc: the <code>[[repo]]</code> set plus <code>[runner]</code>/<code>[status]</code>/<code>[queue]</code>/<code>[worktree]</code> blocks, and optionally <code>[worker] node</code>/<code>node_token_env</code> for the entity-plane worker. <code>tamias-driver-bupha deploy</code> merges the manifest-owned fields (<code>tunnel.public_url</code>, <code>trigger.listen</code>, <code>trigger.kind</code>) into it and writes <code>~/.config/bupha/bundles/&lt;name&gt;.toml</code> — the config BOTH provider verbs consume: <code>host --config</code> (the watcher) and <code>worker --config</code> (the ci-job consumer).</li></ul><p>A bundle declares <strong>two services, one per ingress mode</strong> (ADR-0007): <code>watch</code>/<code>watch-docs</code> runs <code>tamias-driver-bupha host</code> — the standalone/dev watcher behind <code>provider.ingress</code>&#39;s webhook listener — and <code>worker</code>/<code>worker-docs</code> runs <code>tamias-driver-bupha worker</code> — the substrate/production consumer (P-002) that polls <code>kind=&quot;ci-job&quot;</code> entities on the hypha/peregrin node named by <code>[worker] node</code>. Enable ONE: both at once would fight over the listener port and double-run pushes.</p><p>Secrets are env-var <strong>names</strong> everywhere (<code>secret_env</code>, <code>token_env</code>); values resolve env → <strong>cuora</strong> (<code>cuora://bupha/&lt;NAME&gt;</code> via the <code>cuora</code> CLI — canonical, T-056; every fleet secret migrated there in T-059) → <code>~/.config/bupha/env</code> (the dev-mode / no-cuora fallback — the OS-keyring leg was dropped post-T-077; the file is retired and no unit sets <code>EnvironmentFile</code>). Seed/rotate with <code>printf &#39;%s&#39; &quot;$VALUE&quot; | cuora put cuora://bupha/&lt;NAME&gt;</code>. Never a value in either file.</p><blockquote><p><strong>Ingress note (ADR-0007).</strong> The <code>provider.ingress</code> block + <code>hooks register</code> wire the bupha webhook listener — the <strong>standalone/dev</strong> ingress for deployments with no peregrin. Production webhook/forge ingress is a peregrin campaign listener that normalizes deliveries through bupha&#39;s <code>Trigger</code> semantics and enqueues <code>ci-job</code> via <code>ci.enqueue</code> — consumed by the bundle&#39;s <code>worker</code> service, not its <code>watch</code> service.</p></blockquote><h2 id="install-→-deploy-→-hooks" tabindex="-1">Install → deploy → hooks <a class="header-anchor" href="#install-→-deploy-→-hooks" aria-label="Permalink to &quot;Install → deploy → hooks&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tamias</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">re</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">f</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # fetch + unpack; driver install is a no-op</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tamias</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">bundl</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # render the provider unit AND write</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                                # bundles/&lt;name&gt;.toml from fleet.toml + ingress</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tamias</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> driver</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">bundl</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hooks</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> register</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dry-run</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # webhook plan</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tamias</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> driver</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">bundl</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hooks</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> register</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">             # upsert GitHub hooks</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tamias</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">uni</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # start the watcher (e.g. bupha-watch-docs)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tamias</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> uninstall</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">bundl</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # remove unit + bundles/&lt;name&gt;.toml</span></span></code></pre></div><p><code>tamias driver exec &lt;bundle&gt;</code> verbs: <code>hooks register</code> (create/update the declared forge hooks), <code>health</code> (ping <code>/hook</code></p><ul><li>unit probe, JSON), <code>status</code> (per-unit is-active/is-enabled), <code>logs</code> (journalctl over the provider units). <code>tamias driver config-schema &lt;bundle&gt;</code> prints the JSON Schema of the operator config <code>deploy</code> writes.</li></ul><p>The driver — <code>tamias-driver-bupha</code>, built from <code>crates/bupha-driver</code> — is dual-surface: the tamias verbs above plus the pavo view verbs (<code>manifest</code>/<code>capabilities</code>/<code>serve</code>) that serve bupha&#39;s read-only CI views. tamias finds it on <code>PATH</code> or in <code>$TAMIAS_HOME/drivers/</code>.</p><h2 id="writing-your-own-bundle" tabindex="-1">Writing your own bundle <a class="header-anchor" href="#writing-your-own-bundle" aria-label="Permalink to &quot;Writing your own bundle&quot;">​</a></h2><ol><li>Copy <code>libraries/docs-deploy/</code> — it&#39;s the smaller template.</li><li>Edit <code>fleet.toml</code>: one <code>[[repo]]</code> per watched repo (<code>name</code>/<code>dir</code>/<code>branch</code>; <code>events = [&quot;push&quot;, &quot;pull_request&quot;]</code> opts into PR deliveries), the <code>[runner]</code> your pipelines need (<code>shell</code> + <code>cmd</code>, <code>gha</code> + <code>workflow</code>, <code>dagger</code>, …), and <code>[status].context</code> for the commit-status label.</li><li>Edit <code>tamias.yaml</code>: <code>provider.services[]</code> execs should be <code>tamias-driver-bupha host --config ~/.config/bupha/bundles/&lt;name&gt;.toml</code> for the watcher and <code>tamias-driver-bupha worker --config ~/.config/bupha/bundles/&lt;name&gt;.toml</code> for the entity-plane consumer (the driver binary from <code>$TAMIAS_HOME/drivers/</code> or <code>PATH</code> — both verbs run the engine in-process); pick <strong>unique service names</strong> — the unit is <code>&lt;provider.name&gt;-&lt;service&gt;</code>, and two bundles sharing <code>bupha-watch.service</code>/<code>bupha-worker.service</code> would overwrite each other (ci-gate owns <code>watch</code>+<code>worker</code>, docs-deploy owns <code>watch-docs</code>+<code>worker-docs</code>). Give <code>ingress[]</code> a distinct <code>listen</code> port and <code>public_url</code>, and one <code>hooks[]</code> entry per <code>[[repo]]</code>. A substrate-mode bundle still declares <code>ingress[]</code> (it&#39;s the standalone fallback + the source of <code>tunnel.public_url</code>/<code>trigger.listen</code> in the generated config) but only enables the worker unit.</li><li><code>bupha runs --config fleet.toml</code> (dev CLI) smoke-checks the payload parses as a <code>Config</code> before you publish.</li></ol><p>Two watchers can watch the same repo: GitHub delivers every push to both hook URLs and each fleet&#39;s <code>branch</code> filter keeps only its own refs — <code>main</code> for the gate, <code>docs</code> for deploys. Overlap costs a filtered delivery, not a double run.</p><p>Coming from a peregrin campaign instead? The dev CLI&#39;s <code>bupha import &lt;campaign.yaml&gt;</code> translates the github-webhook + git-job + github-status shape into a <code>bupha.yaml</code> fleet config — a head start for the <code>fleet.toml</code> inside step 2.</p>`,17)])])}const u=s(a,[["render",d]]);export{k as __pageData,u as default};
